import 'dart:async';
import 'package:flutter/material.dart';

void main() => runApp(const MyApp());

class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'StreamBuilder Demo',
      theme: ThemeData(colorSchemeSeed: Colors.indigo, useMaterial3: true),
      home: const StreamCounterPage(),
    );
  }
}

/// 用 StreamController 手动驱动的实时计数器
class StreamCounterPage extends StatefulWidget {
  const StreamCounterPage({super.key});

  @override
  State<StreamCounterPage> createState() => _StreamCounterPageState();
}

class _StreamCounterPageState extends State<StreamCounterPage> {
  // 1) 广播流：可被多个 StreamBuilder 同时订阅
  final StreamController<int> _controller = StreamController<int>.broadcast();
  int _count = 0;
  Timer? _timer;

  // 2) 提前把「只取偶数 + 转字符串」的流算好，避免在 build 里反复创建
  late final Stream<String> _evenText = _controller.stream
      .where((n) => n % 2 == 0)
      .map((n) => '当前是第 $n 次（偶数）');

  @override
  void initState() {
    super.initState();
    // 3) 每秒向流中推送一次自增数据
    _timer = Timer.periodic(const Duration(seconds: 1), (_) {
      _count += 1;
      _controller.sink.add(_count);
    });
  }

  @override
  void dispose() {
    // 4) 必须释放资源，否则内存泄漏 / 崩溃
    _timer?.cancel();
    _controller.close();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('StreamBuilder 实战')),
      body: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            // 5) StreamBuilder 订阅流，收到事件就重建这个子树
            StreamBuilder<int>(
              stream: _controller.stream,
              initialData: 0,
              builder: (context, snapshot) {
                if (snapshot.hasError) {
                  return Text('出错了：${snapshot.error}');
                }
                if (snapshot.connectionState == ConnectionState.waiting) {
                  return const CircularProgressIndicator();
                }
                return Text(
                  '计数：${snapshot.data}',
                  style: Theme.of(context).textTheme.headlineMedium,
                );
              },
            ),
            const SizedBox(height: 24),
            // 6) 同一个广播流可以被第二个订阅者复用
            StreamBuilder<String>(
              stream: _evenText,
              builder: (context, snapshot) => Text(
                snapshot.data ?? '等待偶数……',
                style: Theme.of(context).textTheme.bodyLarge,
              ),
            ),
          ],
        ),
      ),
    );
  }
}

